/**
 * FAQ 답변의 첫 문장 경계를 찾는다 — 표시 전용 유틸.
 *
 * 원문(body.html 333~361행)은 여덟 개 답변 모두 **첫 문장을 `<strong>` 으로** 감싸고
 * 나머지를 평문으로 둔다. 그런데 모듈은 답변을 **평문 문자열 하나**로 저장한다
 * (`faq` 도메인 `answer` 키) — 강조 위치가 데이터에 없다. 그래서 표시 계층에서
 * 첫 문장 경계를 추정해 그 문장만 굵게 렌더한다 (COPY POLICY: 문구는 만들지 않는다).
 *
 * 규칙:
 *   - 경계는 **마침표(`.`) + 공백 + 뒤에 더 있는 텍스트** 인 첫 지점이다.
 *   - 뒤에 텍스트가 없으면 나누지 않는다 — 한 문장짜리 답변은 평문으로 렌더된다
 *     (답변 전체를 `<strong>` 으로 감싸는 일이 없다).
 *   - 문장 부호를 바꾸지도, 공백을 다듬지도 않는다. `lead + rest` 는 저장값과
 *     **글자 단위로 같다**(공백 포함).
 *   - 다른 부호(`?` `!` 등)로 대신 나누지 않는다. 경계가 없으면 평문이다.
 *
 * 한계(README 의 [알려진 한계] 참조): 강조 위치를 데이터가 아니라 첫 문장에서
 * 추정하므로, 관리자가 답변을 다시 쓰면 굵게 나오는 자리도 함께 바뀐다. 또한
 * 원문이 두 문장을 한 번에 굵게 처리한 답변 2건(네. … / 아닙니다. …)은 추정 규칙이
 * 첫 문장만 굵게 하므로 원문보다 굵은 범위가 짧다.
 */
export interface FaqAnswerParts {
    /** `<strong>` 으로 렌더할 첫 문장. 경계가 없으면 null. */
    lead: string | null;
    /** 나머지 텍스트. 경계가 없으면 답변 전체. */
    rest: string;
}
/**
 * 답변을 첫 문장과 나머지로 나눈다.
 *
 * 나눈 결과를 이어 붙이면 입력과 정확히 같다 — 호출자는 두 조각을 그대로 렌더한다.
 */
export declare function splitFaqAnswer(answer: string): FaqAnswerParts;
